package com.nextrade.persistence.entity; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="trade_event",indexes={@Index(name="ix_trade_instrument_time",columnList="instrumentId,executedAt")}) public class TradeEntity { @Id private UUID id; @Column(nullable=false) private UUID buyOrderId; @Column(nullable=false) private UUID sellOrderId; @Column(nullable=false) private UUID buyerId; @Column(nullable=false) private UUID sellerId; @Column(nullable=false) private UUID instrumentId; @Column(nullable=false,precision=19,scale=4) private BigDecimal quantity; @Column(nullable=false,precision=19,scale=4) private BigDecimal price; @Column(nullable=false) private long sequence; @Column(nullable=false) private Instant executedAt; public TradeEntity(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getBuyOrderId(){return buyOrderId;} public void setBuyOrderId(UUID v){buyOrderId=v;} public UUID getSellOrderId(){return sellOrderId;} public void setSellOrderId(UUID v){sellOrderId=v;} public UUID getBuyerId(){return buyerId;} public void setBuyerId(UUID v){buyerId=v;} public UUID getSellerId(){return sellerId;} public void setSellerId(UUID v){sellerId=v;} public UUID getInstrumentId(){return instrumentId;} public void setInstrumentId(UUID v){instrumentId=v;} public BigDecimal getQuantity(){return quantity;} public void setQuantity(BigDecimal v){quantity=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){price=v;} public long getSequence(){return sequence;} public void setSequence(long v){sequence=v;} public Instant getExecutedAt(){return executedAt;} public void setExecutedAt(Instant v){executedAt=v;} }
